package com.wheelwright.evidence.v2.portfolio;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import java.sql.Connection;
import java.time.Instant;
import java.util.*;
import static com.wheelwright.evidence.v2.portfolio.PortfolioJson.*;
import static com.wheelwright.evidence.v2.portfolio.PortfolioRepository.*;

/** Current financial composition from explicit brokerage instruction packages or fungible economic coverage.
 * These predicates do not establish an opening occurrence, Program membership, reservation or execution. */
final class PortfolioPackageEvidence {
 private final PortfolioRepository repo;
 PortfolioPackageEvidence(PortfolioRepository repo){this.repo=repo;}
 record Part(Document position,Document construction,List<ObjectNode> leaves){}
 record Candidate(List<ObjectNode> leaves,List<Document> orders,String basis,boolean coverage){}
 List<List<ObjectNode>> partition(Connection tx,com.wheelwright.evidence.v2.PositionSnapshot snapshot,Map<String,ObjectNode> nodes)throws Exception{
  var latest=new PortfolioSnapshots(repo).current(snapshot.account());if(latest.isEmpty()||!latest.get().snapshotId().equals(snapshot.snapshotId()))return List.of();var artifacts=latestInstructionArtifacts(tx,snapshot.account());var proposed=new LinkedHashMap<String,List<ObjectNode>>();var groups=new HashMap<String,String>();var conflicts=new HashSet<String>();
  for(var order:repo.list(tx,Kind.ORDER,Set.of(snapshot.account()))){var o=order.value();if(!o.path("status").asText().equals("WORKING")||Set.of("Contingent","Cancel Requested","Replace Requested").contains(o.path("sourceStatus").asText())||!o.path("observationCoverage").asText().equals("COMPLETE_SUPPORTED_SCAN")||!fromArtifact(o,artifacts)||!corroborated(o))continue;var selected=matchClosing(o,nodes.values());if(selected.size()<2)continue;String signature=signature(selected),group=o.hasNonNull("brokerGroupId")?o.path("brokerGroupId").asText():order.uri();if(groups.putIfAbsent(signature,group)!=null&&!groups.get(signature).equals(group))conflicts.add(signature);proposed.put(signature,selected);}
  var count=new HashMap<String,Integer>();for(var selected:proposed.values())for(var node:selected)count.merge(key(node),1,Integer::sum);var result=new ArrayList<List<ObjectNode>>();for(var entry:proposed.entrySet())if(!conflicts.contains(entry.getKey())&&entry.getValue().stream().allMatch(n->count.get(key(n))==1))result.add(entry.getValue());return result;
 }
 void reconcile(Connection tx,String account,Instant now)throws Exception{
  var cut=new PortfolioSnapshots(repo).current(account);if(cut.isEmpty())return;
  var parts=new ArrayList<Part>();var nodes=new LinkedHashMap<String,ObjectNode>();var owners=new HashMap<String,List<Part>>();
  for(var p:repo.list(tx,Kind.POSITION,Set.of(account)))if(!p.value().path("state").asText().equals("CLOSED")&&p.value().at("/exposure/status").asText().equals("OBSERVED")&&Objects.equals(p.snapshot(),cut.get().snapshotId())){
   var c=repo.get(tx,p.value().at("/currentConstruction/href").asText()).orElseThrow();var leaves=leaves(c.value().path("composition"));var part=new Part(p,c,leaves);parts.add(part);for(var leaf:leaves){String key=key(leaf);nodes.put(key,leaf);owners.computeIfAbsent(key,k->new ArrayList<>()).add(part);}
  }
  var orders=repo.list(tx,Kind.ORDER,Set.of(account));var candidates=new LinkedHashMap<String,Candidate>();var conflicting=new HashSet<String>();
  Set<String> latest=latestInstructionArtifacts(tx,account);
  for(var order:orders){var o=order.value();if(!o.path("status").asText().equals("WORKING")||Set.of("Contingent","Cancel Requested","Replace Requested").contains(o.path("sourceStatus").asText())||!o.path("observationCoverage").asText().equals("COMPLETE_SUPPORTED_SCAN")||!fromArtifact(o,latest)||!corroborated(o))continue;
   var matched=matchClosing(o,nodes.values());if(matched.isEmpty())continue;String signature=signature(matched);String group=o.hasNonNull("brokerGroupId")?o.path("brokerGroupId").asText():order.uri();var old=candidates.get(signature);
   if(old!=null){String previous=old.orders().getFirst().value().hasNonNull("brokerGroupId")?old.orders().getFirst().value().path("brokerGroupId").asText():old.orders().getFirst().uri();if(!previous.equals(group)){conflicting.add(signature);continue;}var peers=new ArrayList<>(old.orders());peers.add(order);candidates.put(signature,new Candidate(matched,peers,"BROKER_PACKAGE_RECORD",false));}
   else candidates.put(signature,new Candidate(matched,List.of(order),"BROKER_PACKAGE_RECORD",false));
  }
  // Overlapping distinct package interpretations are not arbitrarily selected, even when each looks named.
  var claims=new HashMap<String,Integer>();for(var candidate:candidates.values())for(var leaf:candidate.leaves())claims.merge(key(leaf),1,Integer::sum);
  var consumed=new HashSet<String>();for(var entry:candidates.entrySet()){
   var candidate=entry.getValue();if(conflicting.contains(entry.getKey())||candidate.leaves().stream().anyMatch(n->claims.get(key(n))!=1||owners.getOrDefault(key(n),List.of()).size()!=1))continue;
   if(admit(tx,account,cut.get().snapshotId(),candidate,owners,now))candidate.leaves().forEach(n->consumed.add(key(n)));
  }
  // Economic coverage is an aggregate quantity relationship, not a choice of deliverable shares/tax lots.
  for(var option:nodes.values())if(!consumed.contains(key(option))&&option.path("kind").asText().equals("OPTION")&&option.path("side").asText().equals("SHORT")&&PortfolioRecognition.standardTerms(option.path("terms"))){
   boolean call=option.at("/terms/right").asText().equals("CALL");String underlying=option.at("/terms/underlying/href").asText();long obligations=nodes.values().stream().filter(n->n.path("kind").asText().equals("OPTION")&&(call?n.at("/terms/underlying/href").asText().equals(underlying):true)).count();
   var support=nodes.values().stream().filter(n->!consumed.contains(key(n))&&n.path("side").asText().equals("LONG")&&n.path("currency").equals(option.path("currency"))&&(call?n.path("kind").asText().equals("LONG_SHARES")&&n.at("/instrument/href").asText().equals(underlying):n.path("kind").asText().equals("CASH"))).toList();
   var required=number(option.path("quantity")).multiply(number(option.at("/terms/multiplier")));if(!call)required=required.multiply(number(option.at("/terms/strike")));
   if(obligations==1&&support.size()==1&&number(support.getFirst().path("quantity")).compareTo(required)>=0&&owners.getOrDefault(key(option),List.of()).size()==1&&owners.getOrDefault(key(support.getFirst()),List.of()).size()==1){var selected=List.of(support.getFirst(),option);if(admit(tx,account,cut.get().snapshotId(),new Candidate(selected,List.of(),"AGGREGATE_ECONOMIC_CALCULATION",true),owners,now))selected.forEach(n->consumed.add(key(n)));}
  }
  attachAggregateCoverage(tx,account,cut.get().snapshotId(),now);
  associateCurrentScopes(tx,account,cut.get().snapshotId(),orders,latest,now);
 }
 private boolean admit(Connection tx,String account,String snapshot,Candidate candidate,Map<String,List<Part>> owners,Instant now)throws Exception{
  var selected=new LinkedHashMap<String,Part>();for(var n:candidate.leaves())for(var p:owners.getOrDefault(key(n),List.of()))selected.put(p.position().uri(),p);
  if(selected.isEmpty())return false;var keys=new TreeSet<String>();candidate.leaves().forEach(n->keys.add(key(n)));for(var p:selected.values()){
   if(!(p.position().value().path("state").asText().equals("UNRESOLVED")||selected.size()==1&&p.position().value().path("state").asText().equals("OPEN"))||p.leaves().stream().anyMatch(n->!keys.contains(key(n))))return false;
   if(selected.size()>1&&(p.leaves().size()!=1||!Objects.equals(p.position().sourceKey(),key(p.leaves().getFirst()))||!p.construction().value().at("/recognition/authority/basis").asText().equals("BROKER_HOLDING_OBSERVATION")||p.position().value().at("/stateEvidence/completeness").asText().equals("SCOPED_ACCEPTED")||p.position().value().at("/evaluation/economicComparison").isObject()||p.position().sourceKey()!=null&&p.position().sourceKey().startsWith("position-")))return false;
  }
  var first=selected.values().iterator().next();boolean reuse=selected.size()==1;String pid=reuse?first.position().value().path("id").asText():UUID.randomUUID().toString(),puri="/v2/positions/"+pid;
  var es=array();for(var n:candidate.leaves())for(var e:n.at("/allocation/inventory/evidence"))es.add(e.deepCopy());for(var order:candidate.orders())for(var e:order.value().path("evidence"))es.add(e.deepCopy());
  var proofOrders=new ArrayList<String>();for(var order:candidate.orders()){var facts=order.value().deepCopy();facts.remove(List.of("associations","relatedOrders","warnings"));proofOrders.add(facts.toString());}String proof=com.wheelwright.evidence.v2.BrokerageArtifacts.sha((snapshot+candidate.basis()+candidate.leaves()+proofOrders).getBytes(java.nio.charset.StandardCharsets.UTF_8));
  var definitions=new LinkedHashMap<String,JsonNode>();for(var m:repo.list(tx,Kind.MODEL_VERSION,Set.of()))definitions.put(m.uri(),m.value());
  var shape=first.construction().value().deepCopy();var shapeChildren=array();candidate.leaves().forEach(n->shapeChildren.add(n.deepCopy()));((ObjectNode)shape.path("composition")).set("children",shapeChildren);
  var admission=new PortfolioRecognition.Admission(true,candidate.coverage(),false);String binding="";String oldBinding=first.construction().value().at("/recognition/modelVersion/href").asText();
  if(definitions.containsKey(oldBinding)&&PortfolioRecognition.matches(shape,definitions.get(oldBinding),admission,definitions))binding=oldBinding;
  else for(var definition:definitions.values())if(PortfolioRecognition.matches(shape,definition,admission,definitions)){binding=definition.at("/self/href").asText();break;}
  String interpretedProof=com.wheelwright.evidence.v2.BrokerageArtifacts.sha((proof+"|model:"+binding).getBytes(java.nio.charset.StandardCharsets.UTF_8));
  String retainedProof=first.construction().value().at("/recognition/authority/claimId").asText();
  if(reuse&&oldBinding.equals(binding)&&(retainedProof.equals(proof)||retainedProof.equals(interpretedProof)))return true;
  proof=interpretedProof;

  String cid=UUID.randomUUID().toString(),curi="/v2/constructions/"+cid;var c=first.construction().value().deepCopy();c.put("id",cid).put("createdAt",now.toString()).put("changeKind",reuse?"EVIDENCE_REINTERPRETATION":"INITIAL").put("predecessorStatus",reuse?"KNOWN":"NONE");c.set("self",link(curi));c.set("position",link(puri));if(reuse)c.set("predecessor",first.construction().value().path("self"));else c.putNull("predecessor");var group=obj().put("kind","GROUP").put("nodeId","ROOT").putNull("modelVersion");var members=array();candidate.leaves().forEach(n->members.add(n.deepCopy()));group.set("children",members);c.set("composition",group);c.set("evidence",es);c.set("relationships",array());
  var recognition=obj().put("status","UNCLASSIFIED").putNull("modelVersion");recognition.set("candidateModels",array());recognition.set("reasonCodes",array().add("UNCLASSIFIED_CONSTRUCTION"));recognition.set("evidence",es);recognition.set("authority",PortfolioSources.authority(account,proof,candidate.basis(),"QUALIFIED",es,List.of(curi),"Current financial constituent scope corroborated by "+(candidate.coverage()?"aggregate fungible coverage":"explicit broker closing-instruction leg composition")+" and exact observed inventory, uniquely across competing scopes. No opening occurrence, uninterrupted continuity, Program membership, reservation or execution established."));c.set("recognition",recognition);
  if(!binding.isBlank()){recognition.put("status","VALIDATED");recognition.set("modelVersion",link(binding));recognition.set("reasonCodes",array());}
  c.set("warnings",recognition.path("status").asText().equals("VALIDATED")?array():array().add(warning("UNCLASSIFIED_CONSTRUCTION","/recognition","Explicit package constituents remain inspectable and mathematically evaluable where their terms allow.","A named Model cannot be validated from incompatible or insufficient terms; no name is forced.")));
  if(candidate.coverage()){var support=candidate.leaves().stream().filter(n->!n.path("kind").asText().equals("OPTION")).findFirst().orElseThrow();var option=candidate.leaves().stream().filter(n->n.path("kind").asText().equals("OPTION")).findFirst().orElseThrow();((ArrayNode)c.path("relationships")).add(coverage(account,support,option,now));}
  repo.put(tx,new Document(Kind.CONSTRUCTION,curi,account,c,snapshot,"observed-package:"+signature(candidate.leaves())));
  var p=first.position().value().deepCopy();p.put("id",pid);p.set("self",link(puri));p.set("audit",link(puri+"/audit"));p.set("currentConstruction",link(curi));var heldEvidence=array();for(var leaf:candidate.leaves())for(var ref:leaf.at("/allocation/inventory/evidence"))heldEvidence.add(ref.deepCopy());((ObjectNode)p.path("exposure")).set("evidence",heldEvidence);p.putNull("orders");p.set("evaluation",PortfolioMath.evaluate(c,Map.of(),now));if(reuse)for(String retained:List.of("economicComparison","historicalMarketValue"))if(first.position().value().at("/evaluation/"+retained).isObject())((ObjectNode)p.path("evaluation")).set(retained,first.position().value().at("/evaluation/"+retained).deepCopy());var aliases=array();var unique=new HashSet<String>();for(var part:selected.values())for(var alias:part.position().value().path("sourceIdentifiers"))if(unique.add(alias.toString()))aliases.add(alias.deepCopy());p.set("sourceIdentifiers",aliases);p.set("warnings",array().add(warning("ASSOCIATION_UNRESOLVED","/stateEvidence","Current financial scope and independently readable source holdings remain established to their declared evidence cut.","Package recognition does not prove an opening occurrence, historical cost basis, governance or economic continuity.")));repo.put(tx,new Document(Kind.POSITION,puri,account,p,snapshot,"observed-package:"+signature(candidate.leaves())));
  if(!reuse)for(var old:selected.values())supersede(tx,old,puri,now);
  return true;
 }
 private void supersede(Connection tx,Part old,String successor,Instant now)throws Exception{
  var c=old.construction().value().deepCopy();String cid=UUID.randomUUID().toString(),uri="/v2/constructions/"+cid;c.put("id",cid).put("createdAt",now.toString()).put("changeKind","EVIDENCE_REINTERPRETATION").put("predecessorStatus","KNOWN");c.set("self",link(uri));c.set("predecessor",old.construction().value().path("self"));((ObjectNode)c.path("composition")).set("children",array());c.set("relationships",array());var r=(ObjectNode)c.path("recognition");r.put("status","UNCLASSIFIED").putNull("modelVersion");r.set("reasonCodes",array().add("ASSOCIATION_UNRESOLVED"));c.set("warnings",array().add(warning("ASSOCIATION_UNRESOLVED","/composition","The original singleton interpretation remains inspectable through its predecessor.","This provisional inventory interpretation is superseded by source-backed financial composition. No economic Position merge, event, governance transfer or lifecycle closure asserted.")));repo.put(tx,new Document(Kind.CONSTRUCTION,uri,old.position().account(),c,old.position().snapshot(),old.position().sourceKey()));var p=old.position().value().deepCopy();p.set("currentConstruction",link(uri));((ObjectNode)p.path("exposure")).put("status","SUPERSEDED_INTERPRETATION").set("successorPosition",link(successor));p.set("evaluation",PortfolioMath.evaluate(c,Map.of(),now));((ArrayNode)p.path("warnings")).add(warning("ASSOCIATION_UNRESOLVED","/exposure","Independent GUID, historical construction and source holdings are retained.","Prior provisional interpretation is historical, not a current allocated economic exposure or a proven closure."));repo.put(tx,new Document(Kind.POSITION,old.position().uri(),old.position().account(),p,old.position().snapshot(),old.position().sourceKey()));
 }
 private void associate(Connection tx,Document order,String construction,List<ObjectNode> nodes,ArrayNode evidence,Instant now)throws Exception{
  var value=order.value().deepCopy();var associations=(ArrayNode)value.path("associations");for(var a:associations)if(a.at("/target/href").asText().equals(construction)&&a.path("purpose").asText().equals("CURRENT_OBSERVED_CLOSING_SCOPE"))return;
  var a=obj().put("targetKind","CONSTRUCTION").put("status","ESTABLISHED").put("purpose","CURRENT_OBSERVED_CLOSING_SCOPE");a.set("target",link(construction));var ids=array();nodes.forEach(n->ids.add(n.path("nodeId").asText()));a.set("nodeIds",ids);a.set("evidence",evidence.deepCopy());a.set("authority",PortfolioSources.authority(order.account(),"current-closing:"+order.uri()+":"+construction,"RECONCILED_DOCUMENTED_ACTIVITY","ESTABLISHED",evidence,List.of(order.uri(),construction),"This reported closing instruction addresses the identified current observed nodes; its reported unfilled quantities fit within their uniquely represented quantities. It need not liquidate the whole Construction, and does not attribute holdings changes to a particular fill. This is NOT proof of an opening, held occurrence origin, broker reservation, fill or historical continuity."));associations.add(a);repo.put(tx,new Document(Kind.ORDER,order.uri(),order.account(),value,order.snapshot(),order.sourceKey()));
 }
 private void associateCurrentScopes(Connection tx,String account,String snapshot,List<Document> orders,Set<String> artifacts,Instant now)throws Exception{
  var positions=repo.list(tx,Kind.POSITION,Set.of(account)).stream().filter(p->Objects.equals(p.snapshot(),snapshot)&&p.value().at("/exposure/status").asText().equals("OBSERVED")).toList();var all=new ArrayList<ObjectNode>();var constructions=new LinkedHashMap<String,Document>();for(var p:positions){var c=repo.get(tx,p.value().at("/currentConstruction/href").asText()).orElseThrow();constructions.put(c.uri(),c);all.addAll(leaves(c.value().path("composition")));}
  for(var order:orders){if(!Set.of("WORKING","PARTIALLY_FILLED").contains(order.value().path("status").asText())||!order.value().path("observationCoverage").asText().equals("COMPLETE_SUPPORTED_SCAN")||!fromArtifact(order.value(),artifacts)||!corroborated(order.value()))continue;var matched=matchRemainingClosing(order.value(),all);if(matched.isEmpty())continue;var compatible=new ArrayList<Document>();for(var c:constructions.values()){var keys=new HashSet<String>();leaves(c.value().path("composition")).forEach(n->keys.add(key(n)));if(matched.stream().allMatch(n->keys.contains(key(n))))compatible.add(c);}if(compatible.size()!=1)continue;var evidence=array();for(var n:matched)for(var e:n.at("/allocation/inventory/evidence"))evidence.add(e.deepCopy());for(var e:order.value().path("evidence"))evidence.add(e.deepCopy());associate(tx,order,compatible.getFirst().uri(),matched,evidence,now);}
 }
 private void attachAggregateCoverage(Connection tx,String account,String snapshot,Instant now)throws Exception{
  var holdings=repo.list(tx,Kind.HOLDING,Set.of(account)).stream().filter(h->Objects.equals(h.snapshot(),snapshot)&&h.value().path("side").asText().equals("LONG")).toList();
  for(var position:repo.list(tx,Kind.POSITION,Set.of(account)))if(position.value().at("/exposure/status").asText().equals("OBSERVED")&&Objects.equals(position.snapshot(),snapshot)){
   var old=repo.get(tx,position.value().at("/currentConstruction/href").asText()).orElseThrow();var value=old.value().deepCopy();boolean changed=false;
   for(var option:leaves(value.path("composition")))if(option.path("kind").asText().equals("OPTION")&&option.path("side").asText().equals("SHORT")&&PortfolioRecognition.standardTerms(option.path("terms"))){boolean call=option.at("/terms/right").asText().equals("CALL");boolean present=false;for(var r:value.path("relationships"))if(r.path("kind").asText().equals("ECONOMIC_COVERAGE"))for(var target:r.path("toNodes"))present|=target.asText().equals(option.path("nodeId").asText());if(present)continue;
    var support=holdings.stream().filter(h->number(h.value().path("quantity"))!=null&&(call?h.value().path("unit").asText().equals("SHARE")&&h.value().path("instrument").equals(option.at("/terms/underlying")):h.value().path("unit").asText().equals("MONEY")&&h.value().at("/reportedMarketValue/currency").equals(option.path("currency")))).findFirst();if(support.isEmpty())continue;
    var source=support.get();var leaf=obj().put("nodeId","aggregate-source").put("kind",call?"LONG_SHARES":"CASH").put("currency",option.path("currency").asText());var allocation=obj();allocation.set("holding",source.value().path("self"));var inventory=obj();inventory.set("evidence",source.value().path("evidence"));allocation.set("inventory",inventory);leaf.set("allocation",allocation);var relationship=coverage(account,leaf,option,now);relationship.set("fromNodes",array());((ArrayNode)value.path("relationships")).add(relationship);changed=true;
   }
   if(changed){String id=UUID.randomUUID().toString(),uri="/v2/constructions/"+id;value.put("id",id).put("createdAt",now.toString()).put("changeKind","EVIDENCE_REINTERPRETATION").put("predecessorStatus","KNOWN");value.set("self",link(uri));value.set("predecessor",old.value().path("self"));repo.put(tx,new Document(Kind.CONSTRUCTION,uri,account,value,snapshot,old.sourceKey()));var p=position.value().deepCopy();p.set("currentConstruction",link(uri));repo.put(tx,new Document(Kind.POSITION,position.uri(),account,p,snapshot,position.sourceKey()));}
  }
 }
 private static ObjectNode coverage(String account,ObjectNode support,ObjectNode option,Instant now){boolean cash=support.path("kind").asText().equals("CASH");var amount=number(option.path("quantity")).multiply(number(option.at("/terms/multiplier")));if(cash)amount=amount.multiply(number(option.at("/terms/strike")));var es=array();for(var n:List.of(support,option))for(var e:n.at("/allocation/inventory/evidence"))es.add(e.deepCopy());var r=obj().put("kind","ECONOMIC_COVERAGE").put("quantity",decimal(amount)).put("unit",cash?"MONEY":"SHARE").put("status","QUALIFIED").putNull("effectiveAt").put("coverageSetId","fungible:"+support.at("/allocation/holding/href").asText()).put("selection","AGGREGATE_FUNGIBLE_NO_SPECIFIC_SHARE_SELECTION");if(cash)r.set("currency",support.path("currency"));else r.putNull("currency");r.putNull("relatedPosition");r.set("fromNodes",array().add(support.path("nodeId").asText()));r.set("toNodes",array().add(option.path("nodeId").asText()));r.set("supportHolding",support.at("/allocation/holding"));r.set("evidence",es);r.set("authority",PortfolioSources.authority(account,"coverage:"+option.path("nodeId").asText(),"AGGREGATE_ECONOMIC_CALCULATION","QUALIFIED",es,List.of(support.at("/allocation/holding/href").asText()),"Owned aggregate economic coverage, not reserved collateral, available buying power, or selected shares."));return r;}
 private static List<ObjectNode> matchRemainingClosing(JsonNode order,List<ObjectNode> nodes){var result=new ArrayList<ObjectNode>();var used=new HashSet<String>();for(var leg:order.path("legs")){var requested=number(leg.path("requestedQuantity"));var filled=number(leg.at("/filledQuantity/value"));if(requested==null||filled==null||!leg.path("fillsCoverage").asText().equals("COMPLETE_REPORTED"))return List.of();var remaining=requested.subtract(filled);if(remaining.signum()<0)return List.of();if(remaining.signum()==0)continue;var matches=nodes.stream().filter(n->n.path("instrument").equals(leg.path("instrument"))&&number(n.path("quantity"))!=null&&remaining.compareTo(number(n.path("quantity")))<=0&&leg.path("action").asText().equals(n.path("side").asText().equals("SHORT")?"BUY_TO_CLOSE":"SELL_TO_CLOSE")).toList();if(matches.size()!=1||!used.add(key(matches.getFirst())))return List.of();result.add(matches.getFirst());}return result;}
 private static List<ObjectNode> matchClosing(JsonNode order,Collection<ObjectNode> nodes){var result=new ArrayList<ObjectNode>();var seen=new HashSet<String>();for(var leg:order.path("legs")){var matches=nodes.stream().filter(n->n.path("instrument").equals(leg.path("instrument"))&&number(n.path("quantity"))!=null&&number(n.path("quantity")).compareTo(number(leg.path("requestedQuantity")))==0&&leg.path("action").asText().equals(n.path("side").asText().equals("SHORT")?"BUY_TO_CLOSE":"SELL_TO_CLOSE")).toList();if(matches.size()!=1||!seen.add(key(matches.getFirst())))return List.of();result.add(matches.getFirst());}return result;}
 private static boolean corroborated(JsonNode o){if(!o.hasNonNull("brokerGroupId"))return true;return Set.of("QUALIFIED","ESTABLISHED").contains(o.at("/brokerGroupAuthority/status").asText())&&o.at("/brokerGroupAuthority/basis").asText().equals("BROKER_PACKAGE_RECORD")&&o.at("/brokerGroupAuthority/account").equals(o.path("account"));}
 private static boolean fromArtifact(JsonNode o,Set<String> artifacts){for(var e:o.path("evidence"))for(String artifact:artifacts)if(e.at("/artifact/href").asText().equals("/v2/artifacts/"+artifact))return true;return false;}
 private static Set<String> latestInstructionArtifacts(Connection tx,String account)throws Exception{return latestArtifacts(tx,account,false);}
 static Set<String> latestArtifacts(Connection tx,String account,boolean complex)throws Exception{
  record Page(String id,String artifact,Instant at){}var pages=new ArrayList<Page>();try(var q=tx.prepareStatement("SELECT i.import_id,a.artifact_id,i.imported_at FROM brokerage_artifact a JOIN brokerage_import i ON a.account=i.account AND a.artifact_id=i.artifact_id WHERE a.account=? AND i.file_type='API_ORDERS' AND i.status='ACCEPTED' AND i.original_filename "+(complex?"LIKE":"NOT LIKE")+" 'tastytrade-complex-orders-%'")){q.setString(1,account);try(var r=q.executeQuery()){while(r.next())pages.add(new Page(r.getString(1),r.getString(2),Instant.parse(r.getString(3))));}}if(pages.isEmpty())return Set.of();var latest=pages.stream().max(Comparator.comparing(Page::at).thenComparing(Page::id)).orElseThrow();String scan=latest.id().matches("[0-9a-f-]{36}-[0-9]+")?latest.id().substring(0,36):latest.id();var result=new HashSet<String>();for(var page:pages)if(page.id().equals(scan)||page.id().startsWith(scan+"-"))result.add(page.artifact());return result;
 }
 private static String key(ObjectNode n){return n.at("/allocation/inventory/key").asText();}
 private static String signature(List<ObjectNode> nodes){var keys=new TreeSet<String>();nodes.forEach(n->keys.add(key(n)));return keys.toString();}
}
